import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const DATA_DIR = path.join(__dirname, 'data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Relative path of the file within the data directory.',
          },
        },
        required: ['path'],
        additionalProperties: false,
      },
    },
  ];
}

function resolveWithinData(inputPath) {
  if (typeof inputPath !== 'string' || inputPath.length === 0) {
    throw new Error('path is required and must be a non-empty string');
  }
  if (path.isAbsolute(inputPath)) {
    throw new Error('path must be relative to the data directory');
  }
  const resolved = path.resolve(DATA_DIR, inputPath);
  const rel = path.relative(DATA_DIR, resolved);
  if (rel === '' || rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('path must not traverse outside the data directory');
  }
  return { resolved, rel };
}

export async function callTool(name, arguments_ = {}) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }
  const { resolved, rel } = resolveWithinData(arguments_.path);
  let stat;
  try {
    stat = fs.statSync(resolved);
  } catch (e) {
    throw new Error('File not found: ' + arguments_.path);
  }
  if (!stat.isFile()) {
    throw new Error('Not a file: ' + arguments_.path);
  }
  const ext = path.extname(rel).toLowerCase();
  const text = `path: ${rel}\nsize: ${stat.size} bytes\nextension: ${ext}`;
  return {
    content: [{ type: 'text', text }],
  };
}
